<template><main class="detail"><nav><button @click="$router.back()"><van-icon name="arrow-left"/> 返回资讯流</button><b>ARTICLE</b></nav><section v-if="article" class="article"><img class="cover" :src="cover" @error="imageError($event,article.id)"/><div class="glass"><p class="source">{{source}}　·　{{article.publishTime||'刚刚更新'}}　·　{{views}} 阅读</p><h1>{{title}}</h1><div class="actions"><button :class="{on:liked}" @click="like"><van-icon :name="liked?'good-job':'good-job-o'"/> {{liked?'已赞':'点赞'}}</button><button :class="{on:favorited}" @click="favorite"><van-icon :name="favorited?'star':'star-o'"/> {{favorited?'已收藏':'收藏'}}</button></div><p v-for="(p,i) in text" :key="i" class="paragraph">{{p}}</p><a v-if="article.sourceUrl" :href="article.sourceUrl" target="_blank">新闻来源与完整报道 <van-icon name="arrow"/></a></div></section><section class="recommend"><p>DISCOVER MORE</p><h2>相关推荐</h2><div class="cards"><button v-for="item in related" :key="item.id" @click="go(item)"><img :src="picture(item.id)" @error="imageError($event,item.id)"/><strong>{{translateTitle(item.title)}}</strong><small>{{translateSource(item.author||'新闻资讯')}} · {{english?'Updated live':'实时更新'}}</small></button></div></section></main></template>
<script setup>import{computed,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{useNewsStore}from'../store/modules/news';import{useFavoriteStore}from'../store/modules/favorite';import{useHistoryStore}from'../store/modules/history';import{isEnglish,translateDescription,translateSource,translateTitle}from'../utils/newsTranslation';const route=useRoute(),router=useRouter(),store=useNewsStore(),favorites=useFavoriteStore(),history=useHistoryStore();const article=ref(null),views=ref(0),liked=ref(false),favorited=ref(false);const english=computed(()=>isEnglish());const picture=id=>`https://picsum.photos/seed/nova-article-${encodeURIComponent(id)}/1200/720`;const loadArticle=async id=>{article.value=JSON.parse(sessionStorage.getItem(`live-news:${id}`)||'null')||null;if(!article.value?.title)article.value=await store.getLiveDetail(id)||store.newsDetail;if(article.value?.id){history.addHistory(article.value);history.addHistoryApi(article.value.id).catch(()=>{})}views.value=Number(localStorage.getItem(`views:${id}`)||0)+1;localStorage.setItem(`views:${id}`,views.value);const likes=JSON.parse(localStorage.getItem('news_likes')||'[]');liked.value=likes.some(x=>x.id===article.value?.id);favorites.loadFavorites();favorited.value=favorites.isFavorite(article.value?.id);window.scrollTo({top:0,behavior:'smooth'})};watch(()=>route.params.id,loadArticle,{immediate:true});const cover=computed(()=>article.value?.image||picture(article.value?.id));const title=computed(()=>translateTitle(article.value?.title));const source=computed(()=>translateSource(article.value?.author||'新闻资讯'));const imageError=(e,id)=>e.target.src=picture(`${id}-alternate`);const all=JSON.parse(sessionStorage.getItem('latest-news')||'[]');const related=computed(()=>{const seen=new Set(),currentKey=String(article.value?.title||'').replace(/\s/g,''),rows=[...store.newsList,...all,...(article.value?.relatedNews||[])].filter(x=>{const key=String(x?.title||'').replace(/\s/g,'');if(!key||key===currentKey||x.id===article.value?.id||seen.has(key))return false;seen.add(key);return true});return rows.slice(0,4)});const like=()=>{liked.value=!liked.value;const rows=JSON.parse(localStorage.getItem('news_likes')||'[]');localStorage.setItem('news_likes',JSON.stringify(liked.value?[article.value,...rows.filter(x=>x.id!==article.value.id)]:rows.filter(x=>x.id!==article.value.id)))};const favorite=()=>favorited.value=favorites.toggleLocal(article.value);const text=computed(()=>[article.value?.description||'这是一则来自公开新闻来源的实时资讯。','围绕本条资讯的相关信息正在持续更新。项目展示标题、来源与摘要，并提供原始新闻来源以供核验。','请以新闻原始发布方的后续报道为准。'].map(translateDescription));const go=async item=>{sessionStorage.setItem(`live-news:${item.id}`,JSON.stringify({...item,image:picture(item.id)}));await router.push({name:'NewsDetail',params:{id:item.id}})}</script>
<style scoped>.detail{min-height:100vh;padding:0 clamp(22px,8vw,170px) 80px;background:radial-gradient(circle at 8% 0,#155a69,transparent 38%),radial-gradient(circle at 100% 0,#68429a,transparent 46%),#0b1020;color:#eff5fa}.detail nav{height:76px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.13);font-size:11px;letter-spacing:1.8px;color:#bbcae2}.detail nav button{border:0;background:none;color:#f2f7ff;font-size:14px}.article{max-width:1080px;margin:44px auto}.cover{width:100%;height:min(43vw,500px);border-radius:26px;object-fit:cover;display:block;box-shadow:0 20px 48px rgba(0,0,0,.3)}.glass{max-width:850px;margin:-68px auto 0;position:relative;padding:32px;border:1px solid rgba(255,255,255,.18);border-radius:24px;background:rgba(14,24,43,.76);backdrop-filter:blur(20px)}.source,.recommend>p{margin:0;color:#a5c9d5;font-size:11px;letter-spacing:1px}.glass h1{font-size:clamp(30px,4vw,50px);line-height:1.2;margin:12px 0 18px}.actions{display:flex;gap:10px;margin-bottom:24px}.actions button{border:1px solid rgba(255,255,255,.22);border-radius:22px;background:rgba(255,255,255,.07);color:#eef5ff;padding:9px 14px}.actions .on{background:#3d9bb1;border-color:#3d9bb1}.paragraph{font-size:17px;line-height:1.9;color:#d9e5ef}.glass a{color:#8be3ec}.recommend{max-width:1080px;margin:64px auto}.recommend h2{margin:8px 0 20px;font-size:30px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px}.cards button{padding:0;text-align:left;border:1px solid rgba(255,255,255,.16);border-radius:18px;overflow:hidden;background:rgba(255,255,255,.07);color:#f3f7fb}.cards img{width:100%;height:140px;display:block;object-fit:cover}.cards strong{display:block;padding:13px 13px 5px;font-size:15px;line-height:1.45}.cards small{display:block;padding:0 13px 14px;color:#a8bdd0}</style>
